(function(){if(document.querySelector('.lbar'))document.body.classList.add('has-buybar');
var s=document.getElementById('slides'),b=document.querySelectorAll('.thumbs button');if(!s||!b.length)return;
var rtl=document.documentElement.dir==='rtl';
function mark(i){for(var k=0;k<b.length;k++){b[k].setAttribute('aria-current',k===i?'true':'false')}}
b.forEach(function(x){x.addEventListener('click',function(){var i=Number(x.dataset.i);
s.scrollTo({left:(rtl?-1:1)*i*s.clientWidth,behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});mark(i)})});
s.addEventListener('scroll',function(){var i=Math.round(Math.abs(s.scrollLeft)/s.clientWidth);if(i<b.length)mark(i)},{passive:true})})();
</script>{{template "bottom" .}}

