scripts.home:
// GET /?lang=ar  hero, search form, featured listings, agents, the owners' valuation block
function handle(req) {
  const p = page(req, {});
  const w = publicWhere(p.a);
  let rows = db.query('SELECT * FROM listings WHERE ' + w + ' AND featured = 1 ORDER BY coalesce(published, created_at) DESC, id DESC LIMIT 6');
  if (rows.length === 0) rows = db.query('SELECT * FROM listings WHERE ' + w + ' ORDER BY coalesce(published, created_at) DESC, id DESC LIMIT 6');
  p.featured = rows.map(l => card(l, p.lang, p.t));
  p.agents = db.query('SELECT * FROM agents WHERE active = 1 ORDER BY id LIMIT 12').map(x => agentCard(x, p.lang));
  p.form = searchForm(p.a, p.t, {purpose: '', type: '', community: '', beds: -1, min: 0, max: 0}, p.lang);
  p.about = pick(p.a, 'about', p.lang);
  if (p.theme.boutique) Object.assign(p, boutiqueHome(p));
  return {template: 'home', data: p};
}

// The boutique home page (font = boutique): headline, highlights, numbers counted from the published listings, the
// communities with a photo and their number of homes, the property types with theirs, and up to three real client reviews.
function boutiqueHome(p) {
  const a = p.a, lang = p.lang, t = p.t, w = publicWhere(a), amp = p.amp;
  const one = sql => db.query(sql)[0].n;
  const total = one('SELECT count(*) AS n FROM listings WHERE ' + w);
  const sale = one("SELECT count(*) AS n FROM listings WHERE " + w + " AND purpose = 'sale'");
  const areaRows = db.query("SELECT community, max(coalesce(community_ar, '')) AS ar, count(*) AS n, " +
    "max(CASE WHEN coalesce(image1, '') != '' THEN image1 ELSE '' END) AS image FROM listings WHERE " + w +
    " AND coalesce(community, '') != '' GROUP BY community ORDER BY n DESC, community LIMIT 5");
  const stats = total === 0 ? [] : [
    {n: total, label: t.stat_properties, url: '/search' + p.qs},
    {n: sale, label: t.stat_sale, url: '/search?purpose=sale' + amp},
    {n: total - sale, label: t.stat_rent, url: '/search?purpose=rent' + amp},
    {n: one("SELECT count(DISTINCT community) AS n FROM listings WHERE " + w + " AND coalesce(community, '') != ''"), label: t.stat_communities, url: '/search' + p.qs}];
  const countText = n => n === 1 ? t.one_property : t.n_properties.replace('{n}', n);
  return {eyebrow: pick(a, 'eyebrow', lang) || '', headline: pick(a, 'headline', lang) || p.tagline || p.agencyName,
    accent: pick(a, 'tagline_accent', lang) || '', intro: pick(a, 'intro', lang) || '', aboutImage: a.interior_image || a.story_image || '',
    aboutImage2: a.interior_image && a.story_image ? a.story_image : '', stats: stats,
    areas: areaRows.map(r => ({name: lang === 'ar' && r.ar ? r.ar : r.community, count: countText(r.n), image: r.image,
      url: '/search?community=' + encodeURIComponent(r.community) + amp})),
    types: db.query('SELECT property_type AS type, count(*) AS n FROM listings WHERE ' + w + ' GROUP BY property_type ORDER BY n DESC, property_type')
      .map(r => ({label: t['type_' + r.type] || r.type, n: r.n, url: '/search?type=' + encodeURIComponent(r.type) + amp})),
    highlights: db.query('SELECT * FROM highlights WHERE active = 1 ORDER BY coalesce(position, 99), id LIMIT 4')
      .map(h => ({icon: h.icon, title: pick(h, 'title', lang), text: pick(h, 'text', lang) || ''})),
    testimonials: db.query('SELECT * FROM testimonials WHERE active = 1 ORDER BY coalesce(position, 99), id LIMIT 3')
      .map(r => { const name = r.name || ''; return {quote: pick(r, 'quote', lang), name: name, area: pick(r, 'area', lang) || '', initial: Array.from(name)[0] || ''}; })};
}

scripts.search:
// GET /search?purpose=rent&type=apartment&community=Dubai+Marina&beds=2&min=50000&max=150000&sort=price_asc&page=2
// beds: 0 is a studio, 4 means four or more. Filters are fixed SQL with ? placeholders; only the sort order is chosen from a list.
function handle(req) {
  const p = page(req, {}), qy = req.query, t = p.t;
  const num = (v) => { const n = Math.floor(Number(v)); return n > 0 && n < 1e12 ? n : 0; };
  const f = {purpose: qy.purpose === 'sale' || qy.purpose === 'rent' ? qy.purpose : '', type: TYPES.indexOf(qy.type) >= 0 ? qy.type : '',
    community: String(qy.community || '').trim().slice(0, 80), beds: /^[0-9]$/.test(qy.beds || '') ? Number(qy.beds) : -1,
    min: num(qy.min), max: num(qy.max)};
  const orders = {newest: 'coalesce(published, created_at) DESC, id DESC', price_asc: 'price ASC, id', price_desc: 'price DESC, id'};
  const sort = orders[qy.sort] ? qy.sort : 'newest';
  const where = publicWhere(p.a) + ` AND (? = '' OR purpose = ?) AND (? = '' OR property_type = ?) AND (? = '' OR community = ? COLLATE NOCASE)
    AND (? < 0 OR (? >= 4 AND bedrooms >= 4) OR bedrooms = ?) AND (? = 0 OR price >= ?) AND (? = 0 OR price <= ?)`;
  const args = [f.purpose, f.purpose, f.type, f.type, f.community, f.community, f.beds, f.beds, f.beds, f.min, f.min, f.max, f.max];
  const total = db.query('SELECT COUNT(*) AS n FROM listings WHERE ' + where, ...args)[0].n;
  const size = 6, pages = Math.max(1, Math.ceil(total / size));
  const n = Math.min(pages, Math.max(1, Math.floor(Number(qy.page)) || 1));
  const rows = db.query('SELECT * FROM listings WHERE ' + where + ' ORDER BY ' + orders[sort] + ' LIMIT ? OFFSET ?', ...args, size, (n - 1) * size);
  // Links keep the filters; only sort or page changes.
  const link = (s, pg) => {
    const parts = [];
    if (f.purpose) parts.push('purpose=' + f.purpose);
    if (f.type) parts.push('type=' + f.type);
    if (f.community) parts.push('community=' + encodeURIComponent(f.community));
    if (f.beds >= 0) parts.push('beds=' + f.beds);
    if (f.min) parts.push('min=' + f.min);
    if (f.max) parts.push('max=' + f.max);
    if (s !== 'newest') parts.push('sort=' + s);
    if (pg > 1) parts.push('page=' + pg);
    if (p.lang === 'ar') parts.push('lang=ar');
    return '/search' + (parts.length ? '?' + parts.join('&') : '');
  };
  p.listings = rows.map(l => card(l, p.lang, t));
  p.total = total;
  p.resultsText = (total === 1 ? t.results_one : t.results_n).replace('{n}', total);
  p.form = searchForm(p.a, t, f, p.lang);
  p.sort = sort;
  p.sorts = [{label: t.sort_newest, url: link('newest', 1), on: sort === 'newest'}, {label: t.sort_price_asc, url: link('price_asc', 1), on: sort === 'price_asc'},
    {label: t.sort_price_desc, url: link('price_desc', 1), on: sort === 'price_desc'}];
  p.pageNo = n;
  p.pages = pages;
  p.prev = n > 1 ? link(sort, n - 1) : '';
  p.next = n < pages ? link(sort, n + 1) : '';
  p.clear = '/search' + p.qs;
  p.title = f.purpose === 'rent' ? t.for_rent : f.purpose === 'sale' ? t.for_sale : t.properties;
  return {template: 'search', data: p};
}

