scripts.lead:
// POST /lead  form: kind (enquiry|viewing|callback|valuation), listing_id, name, phone, email, message, date, time, source, lang, website
// Anyone can post here without signing in, so: required fields and length limits, a hidden "website" field that only
// robots fill in, at most 5 leads per phone or email in 24 hours and 30 leads in all per hour.
function handle(req) {
  const f = req.form || {};
  const lang = f.lang === 'ar' ? 'ar' : 'en', qa = lang === 'ar' ? '&lang=ar' : '';
  let source = String(f.source || '');
  if (!/^\/[A-Za-z0-9\/_-]{0,80}$/.test(source) || source.indexOf('//') >= 0) source = '/contact';
  const back = (code) => ({redirect: source + '?error=' + code + qa + '#lead'});
  const kind = KINDS.indexOf(f.kind) >= 0 ? f.kind : 'enquiry';
  if (String(f.website || '').trim() !== '') {
    console.warn('lead ignored: the hidden field was filled in');
    return {redirect: '/thanks?kind=' + kind + qa};
  }
  const name = String(f.name || '').trim(), mail = String(f.email || '').trim().toLowerCase(), message = String(f.message || '').trim();
  const date = String(f.date || '').trim(), time = String(f.time || '').trim();
  // +971 50 123 4567, 00971501234567 and 0501234567 are the same number.
  let phone = digits(f.phone);
  if (phone.indexOf('00') === 0) phone = phone.slice(2);
  else if (phone.length === 10 && phone.indexOf('05') === 0) phone = '971' + phone.slice(1);
  if (name.length < 2 || name.length > 100 || phone.length < 7 || phone.length > 15 || message.length > 2000) return back('error_fields');
  phone = '+' + phone;
  if (mail && (mail.length > 200 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(mail))) return back('error_email');
  if ((kind === 'enquiry' || kind === 'valuation') && message.length < 2) return back('error_fields');
  if (kind === 'viewing' && (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date < dubaiToday())) return back('error_date');
  if (time && !/^\d{2}:\d{2}$/.test(time)) return back('error_date');
  const a = agency();
  let listing = null;
  if (f.listing_id) {
    listing = db.query('SELECT * FROM listings WHERE id = ? AND ' + publicWhere(a), Math.floor(Number(f.listing_id)) || 0)[0];
    if (!listing) return back('error_fields');
  }
  if (kind === 'viewing' && !listing) return back('error_fields');
  const day = utc(-24 * 3600 * 1000), hour = utc(-3600 * 1000);
  const mine = db.query("SELECT COUNT(*) AS n FROM leads WHERE created_at >= ? AND (phone = ? OR (? != '' AND email = ?))", day, phone, mail, mail)[0].n;
  const all = db.query('SELECT COUNT(*) AS n FROM leads WHERE created_at >= ?', hour)[0].n;
  if (mine >= 5 || all >= 30) {
    console.warn('lead refused: ' + (mine >= 5 ? 'too many from ' + phone : 'too many this hour'));
    return {template: 'limit', data: page(req, {}), status: 429};
  }
  const ref = listing ? (listing.reference || '#' + listing.id) : '';
  const r = db.exec(`INSERT INTO leads (listing_id, listing_ref, agent_id, kind, name, phone, email, message, preferred_date, preferred_time, source, status, lang)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'new', ?)`,
    listing ? listing.id : null, ref, listing ? listing.agent_id : null, kind, name, phone, mail, message, kind === 'viewing' ? date : '', kind === 'viewing' ? time : '', source, lang);
  const labels = {enquiry: 'enquiry', viewing: 'viewing request', callback: 'callback request', valuation: 'valuation request'};
  try {
    notify.owner({subject: ('New ' + labels[kind] + ': ' + (ref ? ref + ', ' : '') + name.slice(0, 40) + ', ' + phone).slice(0, 150),
      text: 'Lead #' + r.lastInsertId + '\nName: ' + name + '\nPhone: ' + phone + (mail ? '\nEmail: ' + mail : '') +
        (listing ? '\nListing: ' + ref + ' ' + listing.title + '\n' + req.origin + '/l/' + listing.id : '') +
        (kind === 'viewing' ? '\nPreferred: ' + date + (time ? ' ' + time : '') : '') + (message ? '\n\n' + message : '')});
  } catch (e) { console.warn('owner not notified: ' + e); }
  if (mail) {
    const t = texts(lang);
    const fill = (s) => s.replace(/\{name\}/g, name).replace(/\{agency\}/g, pick(a, 'name', lang)).replace(/\{kind\}/g, t['kind_' + kind])
      .replace(/\{ref\}/g, ref || '-').replace(/\{phone\}/g, phone).replace(/\{agency_phone\}/g, a.phone || a.whatsapp || '');
    try { email.send({to: mail, subject: fill(t.email_subject), text: fill(t.email_body)}); } catch (e) { console.warn('confirmation not sent: ' + e); }
  }
  return {redirect: '/thanks?kind=' + kind + qa};
}

