scripts.daily_report:
// Job: every morning, email (and WhatsApp, if turned on) the owner what needs attention.
// It runs once a day, so "new" means the last 24 hours.
function handle(req) {
  const since = utc(-24 * 3600 * 1000);
  const kinds = db.query("SELECT kind, COUNT(*) AS n FROM leads WHERE created_at >= ? AND status != 'spam' GROUP BY kind ORDER BY kind", since);
  let fresh = 0;
  for (const k of kinds) fresh += k.n;
  const waiting = db.query("SELECT id, kind, name, phone FROM leads WHERE status = 'new' AND created_at < ? ORDER BY id LIMIT 20", since);
  const waitingAll = db.query("SELECT COUNT(*) AS n FROM leads WHERE status = 'new' AND created_at < ?", since)[0].n;
  const noPermit = db.query("SELECT reference, title FROM listings WHERE status IN ('available', 'reserved') AND trim(coalesce(permit_number, '')) = '' ORDER BY id LIMIT 20");
  const stale = db.query("SELECT reference, title FROM listings WHERE status = 'available' AND coalesce(published, created_at) < ? ORDER BY id LIMIT 20", utc(-60 * 24 * 3600 * 1000));
  if (fresh === 0 && waitingAll === 0 && noPermit.length === 0 && stale.length === 0) return {text: 'nothing to report'};
  const hidden = agency().hide_without_permit !== 0;
  const s = (n, one, many) => n + ' ' + (n === 1 ? one : many);
  const summary = s(fresh, 'new lead', 'new leads') + ' in the last 24 hours, ' + waitingAll + ' waiting over 24 hours, ' + s(noPermit.length, 'listing', 'listings') + ' without a permit number';
  let text = 'New leads in the last 24 hours: ' + fresh + '\n' + kinds.map(k => '  ' + k.kind + ': ' + k.n).join('\n');
  text += '\n\nLeads still "new" after 24 hours: ' + waitingAll + '\n' + waiting.map(l => '  #' + l.id + ' ' + l.kind + ', ' + l.name + ', ' + l.phone).join('\n');
  text += '\n\nListings without a permit number' + (hidden ? ' (not shown on the site)' : '') + ': ' + noPermit.length + '\n' + noPermit.map(l => '  ' + l.reference + ' ' + l.title).join('\n');
  text += '\n\nListings available for more than 60 days: ' + stale.length + '\n' + stale.map(l => '  ' + l.reference + ' ' + l.title).join('\n');
  try { notify.owner({subject: 'Leads: ' + summary, text: text}); } catch (e) { console.warn('owner not notified: ' + e); }
  return {text: summary + ', ' + s(stale.length, 'listing', 'listings') + ' older than 60 days'};
}

scripts.admin_change:
// on_admin_change: runs right after the owner or staff adds, changes or deletes a row in the admin panel.
// Leads: keeps the listing reference (shown in the viewings calendar) and the agent in line with the listing, and emails the
// visitor a confirmation when the owner sets a lead to viewing booked with a date, or moves a booked viewing to another date or time.
// Listings need nothing here: sold, rented and hidden listings already disappear from every public page.
function handle(req) {
  const b = req.body;
  if (b.table !== 'leads' || b.action === 'delete' || !b.row) return {text: 'nothing to do'};
  const lead = b.row, before = b.before;
  const listing = lead.listing_id ? db.query('SELECT * FROM listings WHERE id = ?', lead.listing_id)[0] || null : null;
  const ref = listing ? (listing.reference || '#' + listing.id) : '';
  const agentId = lead.agent_id || (listing ? listing.agent_id : null) || null;
  if ((lead.listing_ref || '') !== ref || agentId !== lead.agent_id) {
    db.exec('UPDATE leads SET listing_ref = ?, agent_id = ? WHERE id = ?', ref, agentId, lead.id);
  }
  if (lead.status !== 'viewing_booked') return {text: 'saved'};
  const date = String(lead.preferred_date || '').trim(), time = String(lead.preferred_time || '').trim();
  // was: the visitor already had a confirmation for the viewing as it was before this change.
  const bDate = before ? String(before.preferred_date || '').trim() : '', bTime = before ? String(before.preferred_time || '').trim() : '';
  const was = !!before && before.status === 'viewing_booked' && /^\d{4}-\d{2}-\d{2}$/.test(bDate) && (!bTime || /^\d{2}:\d{2}$/.test(bTime));
  if (was && bDate === date && bTime === time) return {text: 'viewing unchanged'};
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || (time && !/^\d{2}:\d{2}$/.test(time))) {
    console.warn('lead ' + lead.id + ': viewing booked without a date (YYYY-MM-DD) or with a time not written HH:MM, so the visitor was not emailed');
    return {text: 'no date: visitor not emailed'};
  }
  const to = String(lead.email || '').trim();
  if (!to) return {text: 'no email address: call the visitor on ' + lead.phone};
  const lang = lead.lang === 'ar' ? 'ar' : 'en', t = texts(lang), a = agency();
  if (!t.email_viewing_subject || !t.email_viewing_body) {
    console.warn('add the texts email_viewing_subject and email_viewing_body to email viewing confirmations');
    return {text: 'texts missing: visitor not emailed'};
  }
  const agent = agentId ? db.query('SELECT * FROM agents WHERE id = ?', agentId)[0] : null;
  const phone = (agent && (agent.phone || agent.whatsapp)) || a.phone || a.whatsapp || '';
  const who = agent || a;
  // Link to the listing only while visitors can still open it.
  const open = !!listing && db.query('SELECT id FROM listings WHERE id = ? AND ' + publicWhere(a), listing.id).length > 0;
  const vars = {name: lead.name, agency: pick(a, 'name', lang), ref: ref || '-', title: listing ? pick(listing, 'title', lang) : '',
    place: listing ? [listing.building, listing.community, listing.emirate].filter(Boolean).join(', ') : '', date: date,
    time: time || t.viewing_time_tbc || '-', agent_contact: [pick(who, 'name', lang), phone, who.email].filter(Boolean).join('\n'),
    agent_phone: phone, link: open ? req.origin + '/l/' + listing.id + (lang === 'ar' ? '?lang=ar' : '') : ''};
  const fill = (s) => s.replace(/\{(\w+)\}/g, (m, k) => vars[k] === undefined ? m : String(vars[k])).replace(/\n{3,}/g, '\n\n');
  try {
    email.send({to: to, subject: fill(t.email_viewing_subject).slice(0, 150), text: fill(t.email_viewing_body)});
  } catch (e) {
    console.warn('viewing confirmation not sent: ' + e);
    return {text: 'viewing confirmation not sent'};
  }
  return {text: (was ? 'new viewing time' : 'viewing confirmation') + ' emailed to ' + to};
}

lib.common:
// Helpers shared by every script, job and tool of the site (lib entries run before each of them).
const TYPES = ['apartment', 'villa', 'townhouse', 'penthouse', 'office', 'shop', 'land'];
const HOMES = ['apartment', 'villa', 'townhouse', 'penthouse'];
const KINDS = ['enquiry', 'viewing', 'callback', 'valuation'];
function langOf(req) {
  const l = (req.query && req.query.lang) || (req.form && req.form.lang) || (req.body && req.body.lang);
  return l === 'ar' ? 'ar' : 'en';
}
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function agency() { return db.query('SELECT * FROM agency ORDER BY id LIMIT 1')[0]; }
function digits(s) { return String(s || '').replace(/[^0-9]/g, ''); }
// 1850000 -> "1,850,000"
function aed(n) {
  const s = String(Math.round(Number(n) || 0));
  let out = '';
  for (let i = 0; i < s.length; i++) out += (i > 0 && (s.length - i) % 3 === 0 ? ',' : '') + s[i];
  return out;
}
// A property price with its currency in the page's language, from texts.money: "AED 2,350,000" or "2,350,000 د.إ".
// Property prices are whole dirhams, so no decimals; the template keeps it on one line (class "price").
function priceText(n, t) { return (t.money || 'AED {n}').replace('{n}', aed(n)); }
// 'YYYY-MM-DD' (or a created_at) as "19 Nov 2026" or "19 نوفمبر 2026" (month names from texts.months, Western digits).
function longDate(ymd, t) {
  const p = String(ymd || '').slice(0, 10).split('-'), m = String(t.months || '').split('|');
  if (p.length !== 3 || m.length !== 12 || !(Number(p[1]) >= 1)) return String(ymd || '');
  return Number(p[2]) + ' ' + m[Number(p[1]) - 1] + ' ' + p[0];
}
// The Arabic value of a column pair such as name / name_ar, or the English one when there is none.
function pick(row, col, lang) { return lang === 'ar' && row[col + '_ar'] ? row[col + '_ar'] : row[col]; }
// An emirate in the page's language (texts emirate_dubai, emirate_abu_dhabi ...).
function emirateName(e, t) { return e ? t['emirate_' + String(e).toLowerCase().replace(/[^a-z]+/g, '_')] || e : ''; }
// "Q4 2028" as "Q4 2028" or "الربع 4 من 2028" (texts.handover_quarter); anything else as written.
function handoverText(s, t) {
  const m = /^\s*Q([1-4])\s*(\d{4})\s*$/i.exec(String(s || ''));
  return m && t.handover_quarter ? t.handover_quarter.replace('{q}', m[1]).replace('{y}', m[2]) : (s || '');
}
// UTC "YYYY-MM-DD HH:MM:SS", as in created_at, shifted by ms.
function utc(ms) { return new Date(Date.now() + (ms || 0)).toISOString().replace('T', ' ').slice(0, 19); }
// Today's date in Dubai (UTC+4), "YYYY-MM-DD".
function dubaiToday() { return new Date(Date.now() + 4 * 3600 * 1000).toISOString().slice(0, 10); }
// The rule for what visitors may see: available or reserved, and with a permit number
// unless the owner turned "hide without permit" off. Constant SQL, no visitor data.
function publicWhere(a) {
  return "status IN ('available', 'reserved')" + (a.hide_without_permit === 0 ? '' : " AND trim(coalesce(permit_number, '')) != ''");
}
// The current address in the other language, keeping the other query parameters (filters, page, error).
function langLink(req, lang) {
  const q = [];
  for (const k in req.query) if (k !== 'lang') q.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  if (lang === 'ar') q.push('lang=ar');
  return req.path + (q.length ? '?' + q.join('&') : '');
}
function page(req, extra) {
  const lang = langOf(req), a = agency(), t = texts(lang);
  const qs = lang === 'ar' ? '?lang=ar' : '';
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: t, a: a, theme: theme(a),
    agencyName: pick(a, 'name', lang), tagline: pick(a, 'tagline', lang), story: pick(a, 'story', lang) || '',
    address: pick(a, 'address', lang) || '', legalName: pick(a, 'legal_name', lang) || '',
    officeLabel: pick(a, 'office_reg_label', lang) || '', officeNo: a.office_reg_value || '',
    path: req.path, qs: qs, amp: lang === 'ar' ? '&lang=ar' : '', here: req.path + qs,
    langEn: langLink(req, 'en'), langAr: langLink(req, 'ar'),
    wa: digits(a.whatsapp), phone: a.phone || '', title: '', minDate: dubaiToday()};
  const e = req.query && req.query.error;
  if (e && /^error_[a-z_]+$/.test(e) && t[e]) base.error = t[e];
  for (const k in extra) base[k] = extra[k];
  base.seo = seoOf(req, base, a, 'RealEstateAgent', base.seo);
  return base;
}
// A listing as shown on cards and returned by the tools, with every label in the visitor's language.
function card(l, lang, t) {
  const home = HOMES.indexOf(l.property_type) >= 0 && l.bedrooms !== null;
  const beds = !home ? '' : l.bedrooms === 0 ? t.studio : l.bedrooms + ' ' + (l.bedrooms === 1 ? t.bed : t.beds);
  const baths = l.bathrooms ? l.bathrooms + ' ' + (l.bathrooms === 1 ? t.bath : t.baths) : '';
  const area = l.area_sqft ? aed(l.area_sqft) + ' ' + t.sqft : '';
  const images = [];
  for (let i = 1; i <= 6; i++) if (l['image' + i]) images.push(l['image' + i]);
  return {id: l.id, ref: l.reference || ('#' + l.id), refLabel: t.ref, title: pick(l, 'title', lang), purpose: l.purpose,
    purposeLabel: l.purpose === 'rent' ? t.for_rent : t.for_sale, type: l.property_type, typeLabel: t['type_' + l.property_type] || l.property_type,
    price: aed(l.price), priceNum: l.price, priceText: priceText(l.price, t),
    period: l.purpose !== 'rent' ? '' : l.rent_period === 'monthly' ? t.per_month : t.per_year,
    beds: beds, baths: baths, area: area,
    place: [pick(l, 'building', lang), pick(l, 'community', lang), emirateName(l.emirate, t)].filter(Boolean).join(t.list_sep || ', '),
    community: l.community,
    offplanLabel: l.offplan ? t.offplan : '', reservedLabel: l.status === 'reserved' ? t.reserved : '',
    image: images.length ? images[0] : '', images: images, permit: (l.permit_number || '').trim(),
    url: '/l/' + l.id + (lang === 'ar' ? '?lang=ar' : '')};
}
function agentCard(x, lang) {
  const name = pick(x, 'name', lang) || '';
  return {id: x.id, name: name, initial: Array.from(name)[0] || '', photo: x.photo, phone: x.phone, phoneDigits: digits(x.phone), wa: digits(x.whatsapp),
    email: x.email, brn: x.brn, languages: pick(x, 'languages', lang), bio: pick(x, 'bio', lang), url: '/agents/' + x.id + (lang === 'ar' ? '?lang=ar' : '')};
}
// [{value, label, on}] for a <select> or a radio group.
function opts(values, label, current) { return values.map(v => ({value: v, label: label(v), on: String(v) === String(current)})); }
// Everything the search form needs; f is the current filter {purpose, type, community, beds, min, max}.
// Communities are filtered by their English name; the Arabic one (community_ar) is only the label.
function searchForm(a, t, f, lang) {
  const communities = db.query('SELECT community, max(coalesce(community_ar, \'\')) AS ar FROM listings WHERE ' + publicWhere(a) +
    " AND coalesce(community, '') != '' GROUP BY community ORDER BY community");
  const names = {};
  for (const c of communities) names[c.community] = lang === 'ar' && c.ar ? c.ar : c.community;
  const active = [f.purpose, f.type, f.community, f.beds >= 0 ? 'b' : '', f.min ? 'm' : '', f.max ? 'x' : ''].filter(Boolean).length;
  return {purposes: opts(['', 'sale', 'rent'], v => v === 'rent' ? t.rent : v === 'sale' ? t.buy : t.any, f.purpose),
    types: opts(TYPES, v => t['type_' + v] || v, f.type),
    communities: opts(communities.map(c => c.community), v => names[v], f.community),
    bedsOptions: opts([0, 1, 2, 3, 4], v => v === 0 ? t.studio : v === 4 ? '4+' : String(v), f.beds < 0 ? '' : f.beds),
    min: f.min > 0 ? String(f.min) : '', max: f.max > 0 ? String(f.max) : '', active: active};
}
// The kinds a lead form offers, the chosen one first selected.
function leadKinds(t, kinds, chosen) { return opts(kinds, v => t['kind_' + v], kinds.indexOf(chosen) >= 0 ? chosen : kinds[0]); }

// What search engines, link previews (WhatsApp, Instagram) and AI assistants read in <head>: the page's
// description and picture, and schema.org data. The home page describes the business (kind is its
// schema.org type); a detail page passes item: {type, name, description, image, price, soldOut}.
// The platform adds the canonical address, the other Open Graph tags and the hreflang links itself.
function seoOf(req, d, s, kind, item) {
  const abs = u => !u ? '' : /^https?:\/\//.test(u) ? u : req.origin + u;
  const short = x => { x = String(x || '').replace(/\s+/g, ' ').trim(); return x.length > 160 ? x.slice(0, 159) + '…' : x; };
  const here = req.origin + req.path + (d.lang === 'ar' ? '?lang=ar' : ''), name = pick(s, 'name', d.lang) || '';
  const out = {description: short(d.tagline || d.story), image: abs(s.hero_image || s.logo), icon: abs(s.logo)};
  const put = (o, k, v) => { if (v) o[k] = v; };
  if (item && item.name) {
    out.description = short(item.description) || out.description;
    out.image = abs(item.image) || out.image;
    const j = {'@context': 'https://schema.org', '@type': item.type || 'Product', name: item.name, url: here};
    put(j, 'description', short(item.description));
    put(j, 'image', abs(item.image));
    if (item.type === 'Service') j.provider = {'@type': kind, name: name};
    if (item.price > 0) j.offers = {'@type': 'Offer', price: Number(item.price).toFixed(2), priceCurrency: 'AED', url: here,
      availability: 'https://schema.org/' + (item.soldOut ? 'OutOfStock' : 'InStock')};
    out.jsonld = j;
  } else if (req.path === '/') {
    const j = {'@context': 'https://schema.org', '@type': kind, name: name, url: here};
    put(j, 'description', out.description);
    put(j, 'image', out.image);
    put(j, 'logo', out.icon);
    put(j, 'telephone', s.phone || s.whatsapp);
    put(j, 'address', d.address);
    out.jsonld = j;
  }
  return out;
}

lib.theme:
// Merchant branding from the settings row (brand_color, font, logo), shared by every Renoxium template.
// theme(row) returns {brand, onBrand, brandText, font, style, lux, logo}; the "top" template puts them on <html>
// (data-font, data-style and CSS variables).
// brand: the owner's colour (#rrggbb); when it is empty or not a colour, a quiet slate (or a deep ink for the luxury styles).
// onBrand: white or near-black, whichever reads better on brand (buttons, the intro band).
// brandText: brand darkened until it passes WCAG AA (4.5:1) as text on white, for links and selected states.
// font picks the type pair and the style:
//   modern (IBM Plex Sans + IBM Plex Sans Arabic), classic (Markazi Text headings + IBM Plex), rounded (Rubik): style "standard".
//   heritage (Cormorant Garamond + Jost, Amiri + Noto Naskh Arabic; ivory, antique gold hairlines) and
//   boutique (Gilda Display + DM Sans, Amiri + IBM Plex Sans Arabic; cream paper, terracotta accent, arches): style "standard"
//   with boutique true, so templates keep their layout and may add boutique sections; its look is the boutique template.
//   atelier (Bodoni Moda + Hanken Grotesk, Noto Naskh Arabic + Noto Kufi Arabic; white, near monochrome): style "luxury",
//   which switches to the luxury layout (centred name, full-bleed photo, no boxes, square buttons).
const THEME_DEFAULT_BRAND = '#334155';
const THEME_DEFAULT_INK = '#1f1b17';
const THEME_FONTS = ['modern', 'classic', 'rounded', 'heritage', 'atelier', 'boutique'];
const THEME_DEFAULT_WARM = '#b4643f';
const THEME_LUXURY = ['heritage', 'atelier'];
function themeHex(v) {
  let s = String(v || '').trim().toLowerCase();
  if (/^#?[0-9a-f]{3}$/.test(s)) s = s.replace('#', '').split('').map(c => c + c).join('');
  s = s.replace('#', '');
  return /^[0-9a-f]{6}$/.test(s) ? '#' + s : '';
}
function themeRgb(hex) { return [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)); }
function themeLum(rgb) {
  const c = rgb.map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function themeContrast(a, b) { const x = themeLum(a), y = themeLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); }
function themeToHex(rgb) { return '#' + rgb.map(v => (Math.round(v) < 16 ? '0' : '') + Math.round(v).toString(16)).join(''); }
function theme(row) {
  row = row || {};
  const font = THEME_FONTS.indexOf(row.font) >= 0 ? row.font : 'modern';
  const lux = THEME_LUXURY.indexOf(font) >= 0;
  const boutique = font === 'boutique';
  const brand = themeHex(row.brand_color) || (lux ? THEME_DEFAULT_INK : boutique ? THEME_DEFAULT_WARM : THEME_DEFAULT_BRAND);
  const rgb = themeRgb(brand), white = [255, 255, 255], ink = [26, 23, 22];
  const onBrand = themeContrast(rgb, white) >= themeContrast(rgb, ink) ? '#ffffff' : '#1a1716';
  let text = rgb;
  for (let i = 0; i < 20 && themeContrast(text, white) < 4.5; i++) text = text.map(v => v * 0.9);
  return {brand: brand, onBrand: onBrand, brandText: themeToHex(text), font: font, style: lux ? 'luxury' : 'standard', lux: lux, boutique: boutique, logo: row.logo || ''};
}
